begin read only;
set local statement_timeout='12s';
set local lock_timeout='1s';
set local idle_in_transaction_session_timeout='20s';
set local search_path=pg_catalog,public,pg_temp;
select jsonb_build_object(
 'captured_at',clock_timestamp(),'database',current_database(),'role',current_user,'server_version',current_setting('server_version_num'),'read_only',current_setting('transaction_read_only'),
 'schemas',(select jsonb_agg(nspname order by nspname) from pg_namespace where nspname !~ '^pg_' and nspname not in('information_schema')),
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'schema',n.nspname,'name',p.proname,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'source_md5',md5(replace(p.prosrc,E'\r\n',E'\n')),'definition_md5',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by n.nspname,p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname !~ '^pg_' and n.nspname not in('information_schema','auth','storage','extensions','graphql','graphql_public','realtime','vault','supabase_functions','supabase_migrations','pgsodium','pgsodium_masks') and p.prokind='f'),
 'relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text,'anon_select',has_table_privilege('anon',c.oid,'SELECT'),'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'authenticated_update',has_table_privilege('authenticated',c.oid,'UPDATE')) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in('r','p','v','m') and n.nspname !~ '^pg_' and n.nspname not in('information_schema','auth','storage','extensions','graphql','graphql_public','realtime','vault','supabase_functions','pgsodium','pgsodium_masks')),
 'columns',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default_md5',md5(pg_get_expr(d.adbin,d.adrelid))) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where a.attnum>0 and not a.attisdropped and c.relkind in('r','p','v','m') and (n.nspname in('public','mail_runtime','mail_quota','brand_b1','brand_b2','composio_c1','composio_connect','composio_connect_runtime','composio_connect_reads','simple_mail') or n.nspname='auth' and c.relname='sessions')),
 'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'kind',co.contype,'definition',pg_get_constraintdef(co.oid)) order by n.nspname,c.relname,co.conname) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','mail_runtime','mail_quota','brand_b1','brand_b2','composio_c1','composio_connect','composio_connect_runtime','composio_connect_reads','simple_mail')),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'definition_md5',md5(pg_get_triggerdef(t.oid))) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in('public','mail_runtime','mail_quota','brand_b1','brand_b2','composio_c1','composio_connect','composio_connect_runtime','composio_connect_reads','simple_mail')),
 'policies',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'using_md5',md5(pg_get_expr(p.polqual,p.polrelid)),'check_md5',md5(pg_get_expr(p.polwithcheck,p.polrelid))) order by n.nspname,c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','mail_runtime','mail_quota','brand_b1','brand_b2','composio_c1','composio_connect','composio_connect_runtime','composio_connect_reads','simple_mail')),
 'candidate_guard',(select jsonb_build_object('present',true,'source_md5',md5(replace(prosrc,E'\r\n',E'\n')),'expected_match',md5(replace(prosrc,E'\r\n',E'\n'))='c2c3178219832b68d64bb85d22e39276','old_qualifier',strpos(prosrc,'mail_transport_command.request_key')>0,'new_qualifier',strpos(prosrc,'command_v1.request_key')>0) from pg_proc where oid=to_regprocedure('mail_runtime.command_v1(uuid,text,jsonb,uuid)')),
 'counts',jsonb_build_object('accounts',(select count(*) from public.mail_accounts),'direct_credentials',(select count(*) from public.mail_credentials),'active_superadmins',(select count(*) from public.profiles where role='superadmin' and active),'active_advisors',(select count(*) from public.profiles where role in('seller','seller_admin','closer','closer_admin') and active),'curated_active',(select count(*) from public.operating_brands where code='CURATED' and active)),
 'account_states',(select jsonb_agg(x) from (select status,count(*) count from public.mail_accounts group by status order by status) x),
 'binding_states',(select jsonb_agg(x) from (select status,quota_contract_version,count(*) count from public.mail_provider_bindings group by status,quota_contract_version order by status,quota_contract_version) x)
) as simple_mail_preflight;
rollback;
